// Скрипт печатает ход работы в stderr, а итог — последней строкой stdout: RESULT:{...}
const out = $input.first().json;
const lines = String(out.stdout || '').split(/\r?\n/).filter(Boolean);
const line = [...lines].reverse().find((l) => l.startsWith('RESULT:'));
if (!line) {
  throw new Error('Скрипт не вернул итог. Код выхода ' + out.exitCode + '. ' + String(out.stderr || '').slice(-600));
}
const r = JSON.parse(line.slice('RESULT:'.length));
if (!r.ok) throw new Error(r['ошибка'] || 'проверка не удалась');
return [{ json: r }];

// Уведомление в панель и текст для Telegram. Шлём в Telegram только если
// что-то изменилось с прошлого раза (или это первая проверка).
const r = $('Разобрать итог').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const problems = r['недоступно'] + r['подорожало'] + r['мало_на_складе'];
const head = `Проверено ${r['проверено']}: недоступно ${r['недоступно']}, подорожало ${r['подорожало']}, мало на складе ${r['мало_на_складе']}, без пары в Dsers ${r['без_пары_в_dsers']}`;
const lines = [`🏭 <b>Поставщики</b> · ${esc(head)}`];
if (r['снято_с_продажи']) lines.push(`⛔ Снято с продажи: ${r['снято_с_продажи']}` + r['снятые'].slice(0, 10).map((x) => `
  • ${esc(x['Товар'])}`).join(''));
if (r['возвращено_в_продажу']) lines.push(`✅ Возвращено в продажу: ${r['возвращено_в_продажу']}` + r['возвращённые'].slice(0, 10).map((x) => `
  • ${esc(x['Товар'])}`).join(''));
if (r['изменения'].length) {
  lines.push(`Изменений с прошлой проверки: ${r['изменения'].length}`);
  for (const c of r['изменения'].slice(0, 15)) {
    lines.push(`• ${esc(c['Товар'])}: ${esc(c['Было'])} → <b>${esc(c['Стало'])}</b>${c['Почему'] ? ' (' + esc(c['Почему']) + ')' : ''}`);
  }
  if (r['изменения'].length > 15) lines.push(`… и ещё ${r['изменения'].length - 15}, см. отчёт в панели`);
} else {
  lines.push('Изменений нет.');
}
const send = Boolean($env.TELEGRAM_BOT_TOKEN && $env.TELEGRAM_CHAT_ID) && (r['изменения'].length > 0 || r['первая_проверка'] || r['снято_с_продажи'] > 0 || r['возвращено_в_продажу'] > 0);
return [{ json: {
  kind: problems ? 'warning' : 'info',
  title: `Поставщики: проблемных ${problems}`,
  text: head + (r['изменения'].length ? ` · изменений ${r['изменения'].length}` : '') + (r['снято_с_продажи'] ? ` · снято с продажи ${r['снято_с_продажи']}` : '') + (r['возвращено_в_продажу'] ? ` · возвращено ${r['возвращено_в_продажу']}` : ''),
  telegram_text: lines.join('\n'),
  telegram_on: send,
} }];

// Ответ для панели: цифры, изменения, проблемные товары, ссылка на файл.
const r = $('Разобрать итог').first().json;
let rep = {};
try { rep = $('Отчёт в панель').first().json || {}; } catch (e) { rep = {}; }
const out = {
  проверено: r['проверено'], в_dsers: r['в_dsers'],
  недоступно: r['недоступно'], подорожало: r['подорожало'], мало_на_складе: r['мало_на_складе'],
  в_порядке: r['в_порядке'], без_пары_в_dsers: r['без_пары_в_dsers'], лишних_в_dsers: r['лишних_в_dsers'],
  изменений_с_прошлого_раза: r['изменений_с_прошлого_раза'],
  метаполей_записано: r['метаполей_записано'],
  снято_с_продажи: r['снято_с_продажи'], возвращено_в_продажу: r['возвращено_в_продажу'],
  отчёт: rep.xlsx_url ? { excel: rep.xlsx_url, csv: rep.csv_url } : 'файл не записан — панель не ответила',
};
if (r['снятые'] && r['снятые'].length) out.снятые_с_продажи = r['снятые'];
if (r['возвращённые'] && r['возвращённые'].length) out.возвращённые_в_продажу = r['возвращённые'];
if (r['изменения'].length) out.изменения = r['изменения'];
if (r['проблемные'].length) out.проблемные = r['проблемные'];
return [{ json: out }];
